-- DDL migrations: tables, constraints, indexes, partitioning, sequences, views
CREATE TABLE customers (customer_id NUMBER(10) NOT NULL, first_name VARCHAR2(50 CHAR) NOT NULL, last_name VARCHAR2(50 CHAR) NOT NULL, email VARCHAR2(255) UNIQUE, balance NUMBER(12,2) DEFAULT 0 NOT NULL, notes CLOB, avatar BLOB, created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT pk_customers PRIMARY KEY (customer_id));
CREATE TABLE orders (order_id NUMBER(12) PRIMARY KEY, customer_id NUMBER(10) NOT NULL REFERENCES customers (customer_id), status VARCHAR2(20) DEFAULT 'NEW' CHECK (status IN ('NEW', 'PAID', 'SHIPPED', 'CANCELLED')), total_amount NUMBER(12,2), order_date DATE DEFAULT SYSDATE);
CREATE TABLE order_items (item_id NUMBER PRIMARY KEY, order_id NUMBER NOT NULL, product_id NUMBER NOT NULL, quantity NUMBER(5) NOT NULL, unit_price NUMBER(10,2) NOT NULL, CONSTRAINT fk_oi_order FOREIGN KEY (order_id) REFERENCES orders (order_id) ON DELETE CASCADE, CONSTRAINT chk_qty CHECK (quantity > 0));
CREATE TABLE ids_demo (id NUMBER GENERATED ALWAYS AS IDENTITY, name VARCHAR2(100));
CREATE TABLE ids_demo2 (id NUMBER GENERATED BY DEFAULT AS IDENTITY (START WITH 1000 INCREMENT BY 1), name VARCHAR2(100));
CREATE TABLE line_totals (qty NUMBER, price NUMBER, total NUMBER GENERATED ALWAYS AS (qty * price) VIRTUAL);
CREATE GLOBAL TEMPORARY TABLE temp_staging (id NUMBER, payload VARCHAR2(4000)) ON COMMIT DELETE ROWS;
CREATE TABLE sales_hist (sale_id NUMBER, sale_date DATE NOT NULL, amount NUMBER(12,2)) PARTITION BY RANGE (sale_date) (PARTITION p2023 VALUES LESS THAN (TO_DATE('2024-01-01', 'YYYY-MM-DD')), PARTITION p2024 VALUES LESS THAN (TO_DATE('2025-01-01', 'YYYY-MM-DD')), PARTITION pmax VALUES LESS THAN (MAXVALUE));
CREATE TABLE sales_region (sale_id NUMBER, region VARCHAR2(10), amount NUMBER) PARTITION BY LIST (region) (PARTITION p_east VALUES ('NY', 'NJ'), PARTITION p_west VALUES ('CA', 'WA'), PARTITION p_other VALUES (DEFAULT));
CREATE TABLE sales_hash (sale_id NUMBER, amount NUMBER) PARTITION BY HASH (sale_id) PARTITIONS 8;
CREATE TABLE sales_interval (sale_id NUMBER, sale_date DATE) PARTITION BY RANGE (sale_date) INTERVAL (NUMTOYMINTERVAL(1, 'MONTH')) (PARTITION p0 VALUES LESS THAN (TO_DATE('2020-01-01', 'YYYY-MM-DD')));
CREATE TABLE emp_copy AS SELECT * FROM employees WHERE department_id = 10;
CREATE TABLE emp_empty AS SELECT * FROM employees WHERE 1 = 0;
CREATE TABLE app_config (key VARCHAR2(100) NOT NULL, value VARCHAR2(4000), PRIMARY KEY (key)) TABLESPACE users PCTFREE 10;
CREATE INDEX idx_orders_cust ON orders (customer_id);
CREATE UNIQUE INDEX uq_customers_email ON customers (email);
CREATE INDEX idx_orders_cust_date ON orders (customer_id, order_date DESC);
CREATE INDEX idx_cust_upper_email ON customers (UPPER(email));
CREATE BITMAP INDEX bix_orders_status ON orders (status);
CREATE INDEX idx_sales_local ON sales_hist (sale_date) LOCAL;
CREATE INDEX idx_orders_online ON orders (order_date) TABLESPACE idx_ts ONLINE;
CREATE SEQUENCE customers_seq START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE SEQUENCE orders_seq START WITH 1000 INCREMENT BY 1 MAXVALUE 9999999999 CACHE 20 NOORDER;
CREATE VIEW v_active_customers AS SELECT customer_id, first_name, last_name FROM customers WHERE status = 'ACTIVE';
CREATE OR REPLACE VIEW v_order_summary AS SELECT o.order_id, c.last_name, o.total_amount FROM orders o JOIN customers c ON c.customer_id = o.customer_id WITH READ ONLY;
CREATE OR REPLACE FORCE VIEW v_future AS SELECT * FROM not_yet_created;
CREATE MATERIALIZED VIEW mv_sales_by_month BUILD IMMEDIATE REFRESH FAST ON COMMIT AS SELECT TRUNC(sale_date, 'MM') AS m, SUM(amount) AS total FROM sales_hist GROUP BY TRUNC(sale_date, 'MM');
CREATE SYNONYM emp FOR hr.employees;
CREATE PUBLIC SYNONYM all_emp FOR hr.employees;
ALTER TABLE customers ADD (phone VARCHAR2(30), loyalty_tier VARCHAR2(10) DEFAULT 'BASIC');
ALTER TABLE customers ADD phone2 VARCHAR2(30);
ALTER TABLE customers MODIFY (email VARCHAR2(320) NOT NULL);
ALTER TABLE customers DROP COLUMN phone2;
ALTER TABLE customers RENAME COLUMN loyalty_tier TO tier;
ALTER TABLE customers RENAME TO clients;
ALTER TABLE orders ADD CONSTRAINT fk_orders_cust FOREIGN KEY (customer_id) REFERENCES customers (customer_id);
ALTER TABLE orders DROP CONSTRAINT fk_orders_cust;
ALTER TABLE orders DISABLE CONSTRAINT chk_status;
ALTER TABLE orders ENABLE NOVALIDATE CONSTRAINT chk_status;
ALTER TABLE sales_hist ADD PARTITION p2025 VALUES LESS THAN (TO_DATE('2026-01-01', 'YYYY-MM-DD'));
ALTER TABLE sales_hist DROP PARTITION p2023;
ALTER TABLE sales_hist TRUNCATE PARTITION p2024;
ALTER TABLE orders MOVE TABLESPACE users2;
ALTER INDEX idx_orders_cust REBUILD;
ALTER INDEX idx_orders_cust RENAME TO idx_orders_customer;
ALTER SEQUENCE orders_seq INCREMENT BY 10;
DROP TABLE temp_staging;
DROP TABLE old_orders CASCADE CONSTRAINTS PURGE;
DROP INDEX idx_orders_cust;
DROP VIEW v_future;
DROP SEQUENCE customers_seq;
DROP MATERIALIZED VIEW mv_sales_by_month;
TRUNCATE TABLE audit_log;
